import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 dummy) public {
        // The deployer address is always address(this) in setUp, so the correct owner is address(this).
        // We verify that c.owner() returns the deployer (address(this)).
        // The buggy mutant returns address(0), which will fail this assertion.
