// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // Assume the new owner is not the zero address (the domain where the reference succeeds and the bug reverts)
        vm.assume(newOwner != address(0));
        // Ensure the caller is the current owner
        vm.prank(address(this));
        // Try the transferOwnership call; the reference should succeed (not revert), the buggy version should revert
        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }
        // Assert that the call succeeded (reference property). The buggy version violates this by reverting.
        assertTrue(success);
    }
}

