pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 stakeAmount, address staker) public {
        vm.assume(staker != address(0));
        vm.assume(staker != address(this));
        vm.assume(stakeAmount > 0 && stakeAmount <= 1000000e18);
        deal(address(c.stakingToken()), staker, stakeAmount);
        vm.startPrank(staker);
        c.stakingToken().approve(address(c), stakeAmount);
        c.stake(stakeAmount);
        vm.stopPrank();
        assertTrue(c.totalSupply() == c.balanceOf(staker));
    }
}

