pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        // stake the fuzzed amount with the only staker
        c.stake(amount);
        // assert that total supply equals the sum of all balances (only one staker)
        assertEq(c.totalSupply(), c.balanceOf(address(this)));
    }
}
